program.compute:
options = read('/input/options')
existing = read('/output/selection')
if valid(existing):
    result = existing
else:
    pool = [record['id'] for record in options]
    candidates = []
    for size in range(goal['min_count'], goal['max_count'] + 1):
        for group in combinations(pool, size):
            ids = list(group)
            if valid(ids):
                candidates = candidates + [ids]
                break
        if candidates:
            break
    if candidates:
        result = candidates[0]
    else:
        result = []

program.effects:
if not valid(read('/output/selection')):
    write('/output/selection', result)
if receipt('report') == 'unattempted':
    send('report', 'team', read('/output/selection'))
elif receipt('report') == 'unknown':
    status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

